#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

const int mosfetPin = 3;
const int btnStart = 4;
const int btnMenu = 5;
const int analogPin = A0;

const float R_DIVIDER = 2.0;  // Коэффициент делителя напряжения (10кОм / 10кОм)
const float R_LOAD = 91.0;    // Сопротивление нагрузки

int menuPage = 0;             // Текущая страница меню

// Функция авто-замера VCC относительно внутреннего источника 1.1V
float getVcc() {
  #if defined(__AVR_ATmega328P__) || defined(__AVR_ATmega168__)
    ADMUX = _BV(REFS0) | _BV(MUX3) | _BV(MUX2) | _BV(MUX1);
  #endif
  delay(2); 
  ADCSRA |= _BV(ADSC); 
  while (bit_is_set(ADCSRA, ADSC)); 

  uint8_t low  = ADCL; 
  uint8_t high = ADCH;
  long result = (high << 8) | low;
  float vcc = 1125300L / result; 
  return vcc / 1000.0; 
}

float readBatteryVoltage(float vcc) {
  long sum = 0;
  for(int i=0; i<10; i++) { sum += analogRead(analogPin); delay(2); } 
  float vOut = ((sum / 10.0) * vcc) / 1023.0;
  return vOut * R_DIVIDER;
}

// Функция для прорисовки Progress Bar
void drawProgressBar(int x, int y, int width, int height, int percentage) {
  // Ограничиваем проценты от 0 до 100
  if (percentage > 100) percentage = 100;
  if (percentage < 0) percentage = 0;
  
  // Рисуем рамку индикатора со скругленными углами
  display.drawRoundRect(x, y, width, height, 3, SSD1306_WHITE);
  
  // Рассчитываем ширину внутреннего заполнения шкалы
  int fillWidth = map(percentage, 0, 100, 0, width - 4);
  
  // Рисуем заполнение (делаем отступ 2 пикселя от рамки)
  if (fillWidth > 0) {
    display.fillRoundRect(x + 2, y + 2, fillWidth, height - 4, 1, SSD1306_WHITE);
  }
}

void setup() {
  pinMode(mosfetPin, OUTPUT);
  digitalWrite(mosfetPin, LOW);
  pinMode(btnStart, INPUT_PULLUP);
  pinMode(btnMenu, INPUT_PULLUP);

  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { 
    for(;;);
  }
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
}

void drawMenu() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("--- ER10450S TESTER ---"));
  
  float currentVcc = getVcc();
  
  if (menuPage == 0) {
    display.setCursor(0, 20);
    display.setTextSize(2);
    display.println(F(" READY"));
    display.setTextSize(1);
    display.setCursor(0, 45);
    display.print(F("VCC (Ref): ")); display.print(currentVcc); display.println(F(" V"));
    display.print(F("[START] -> Begin test"));
  } 
  else if (menuPage == 1) {
    display.setCursor(0, 15);
    display.println(F("System Info:"));
    display.print(F("Load Res: ")); display.print(R_LOAD); display.println(F(" Ohm"));
    display.print(F("Divider: 1:")); display.println(R_DIVIDER);
    display.print(F("VCC Auto: ")); display.print(currentVcc); display.println(F(" V"));
    display.setCursor(0, 55);
    display.print(F("[NEXT] to exit info"));
  }
  display.display();
}

void runBatteryTest() {
  float vcc = getVcc();
  
  display.clearDisplay();
  display.setCursor(0, 0);
  display.setTextSize(1);
  display.println(F("TEST RUNNING..."));
  display.println(F("Step 1: Depassivation"));
  display.display();
  
  // 1. Депассивация
  digitalWrite(mosfetPin, HIGH);
  delay(3000);
  digitalWrite(mosfetPin, LOW);
  delay(500);
  
  // 2. Замер OCV
  float V_ocv = readBatteryVoltage(vcc);
  
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println(F("TEST RUNNING..."));
  display.println(F("Step 2: Pulse Load"));
  display.display();
  
  // 3. Импульс нагрузки 100мс
  digitalWrite(mosfetPin, HIGH);
  delay(100);
  float V_load = readBatteryVoltage(vcc);
  digitalWrite(mosfetPin, LOW);
  
  float deltaV = V_ocv - V_load;
  
  // 4. Логика расчета процента заряда (SoC) на основе просадки напряжения
  int socPercent = 0;
  String statusText = "";
  
  if (V_ocv < 2.0) {
    socPercent = 0;
    statusText = "NO BATTERY";
  } else if (deltaV < 0.15 && V_load > 3.4) {
    // Аппроксимация верхнего диапазона (0.00V просадки -> 100%, 0.15V -> 80%)
    socPercent = map(deltaV * 100, 0, 15, 100, 80);
    statusText = "NEW BATTERY";
  } else if (deltaV >= 0.15 && deltaV < 0.35 && V_load > 3.2) {
    // Средний диапазон (0.15V -> 80%, 0.35V -> 40%)
    socPercent = map(deltaV * 100, 15, 35, 80, 40);
    statusText = "GOOD STATUS";
  } else if (deltaV >= 0.35 && deltaV < 0.60) {
    // Низкий диапазон (0.35V -> 40%, 0.60V -> 15%)
    socPercent = map(deltaV * 100, 35, 60, 40, 15);
    statusText = "LOW CHARGE";
  } else {
    // Критический диапазон (выше 0.60V -> от 15% до 0%)
    socPercent = map(deltaV * 100, 60, 100, 15, 0);
    statusText = "REPLACE!";
  }
  
  // Гарантируем рамки 0-100%
  socPercent = constrain(socPercent, 0, 100);

  // 5. Вывод результатов и Progress Bar на OLED
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print(F("OCV: ")); display.print(V_ocv, 2); display.print(F("V "));
  display.print(F("Load: ")); display.print(V_load, 2); display.println(F("V"));
  display.print(F("Drop: ")); display.print(deltaV, 2); display.print(F("V  "));
  display.println(statusText);
  
  // Рисуем Progress Bar посередине экрана
  // Координаты: x=0, y=24, ширина=90, высота=14
  drawProgressBar(0, 24, 90, 14, socPercent);
  
  // Выводим процент цифрами справа от шкалы
  display.setCursor(96, 24);
  display.setTextSize(1);
  display.print(socPercent); display.println(F("%"));
  
  // Нижняя навигационная строка
  display.setCursor(0, 52);
  display.setTextSize(1);
  display.print(F("[MENU] to return"));
  display.display();
  
  // Ожидаем нажатия кнопки Меню для возврата
  while(digitalRead(btnMenu) == HIGH) { delay(10); }
  delay(200); // Антидребезг
}

void loop() {
  drawMenu();
  
  if (digitalRead(btnStart) == LOW && menuPage == 0) {
    delay(200); 
    runBatteryTest();
  }
  
  if (digitalRead(btnMenu) == LOW) {
    delay(200); 
    menuPage++;
    if (menuPage > 1) menuPage = 0;
  }
  
  delay(50);
}
